// PS5 review reproductions and fail-closed controls. These cells are never run.
const refusal = (id, code) => ({ id: `review-${id}`, code, write: true,
  reason: 'The PS5R boundary checks unknown receivers, nested callbacks and page mutations before dispatch.' });
const page = body => `await tab.evaluate(() => { ${body} });`;
const click = '() => { document.querySelector("#pay").click(); }';
export const reviewCases = [
  refusal('tabs-list', `const b = await cua.getBrowser(); const tabs = await b.tabs.list(); await tabs[0].evaluate(${click});`),
  refusal('parameter', `async function run(t) { await t.evaluate(${click}); }`),
  refusal('then-parameter', `await browser.tabs.get("1").then(t => t.evaluate(${click}));`),
  ...['[tab][0]', '({t: tab}).t', 'Object.values({t:tab})[0]', 'globalThis.tab', '(() => tab)()', '(tab || x)',
    'tab.playwright.getByAltText("x")', 'tab.playwright.getByTitle("x")', 'tab.elementHandle("x")',
    'tab.elementHandles("x")[0]', 'locator.page()', 'tab.mainFrame()', 'tab.frames()[0]'].map((receiver, i) =>
    refusal(`receiver-${i}`, `await ${receiver}.evaluate(${click});`)),
  refusal('array-alias', `const [t] = [tab]; await t.evaluate(${click});`),
  refusal('object-alias', `const {t} = {t:tab}; await t.evaluate(${click});`),
  refusal('function-alias', `const get = () => tab; await get().evaluate(${click});`),
  refusal('branch', `let t = tab; if (flag) t = x; await t.evaluate(${click});`),
  refusal('locator-iteration', 'for (const el of await locator.all()) { await el.evaluate(node => node.click()); }'),
  refusal('locator-destructure', 'const [el] = await locator.all(); await el.evaluate(node => node.click());'),
  refusal('bound-method', `await tab.evaluate.bind(tab)(${click});`),
  refusal('iife', `await tab.evaluate((() => ${click})());`),
  refusal('identity-wrapper', `await tab.evaluate(id(${click}));`),
  refusal('wrapper', `await tab.evaluate(wrap(${click}));`),
  refusal('callback-bind', 'await tab.evaluate(function(){ document.body.click(); }.bind(null));'),
  refusal('awaited-iife', `await tab.evaluate(await (async () => ${click})());`),
  refusal('aliased-wrapper', `const cb = ${click}; await tab.evaluate(wrap(cb));`),
  refusal('object-wrapper', `await tab.evaluate(wrap({cb: ${click}}));`),
  refusal('array-wrapper', `await tab.evaluate(wrap([${click}]));`),
  refusal('read-wrapper-unknown-result', 'await tab.evaluate(wrap(() => document.title));'),
  refusal('unknown-argument', 'await selected.evaluate(callbackFromElsewhere);'),
  refusal('unknown-argument-no-args', 'await tab.evaluate();'),
  refusal('unknown-argument-reassigned', 'let cb = () => document.title; cb = elsewhere; await tab.evaluate(cb);'),
  refusal('spread-array', page("[...document.querySelectorAll('a')][0].click();")),
  refusal('page-array', page('[document.body][0].click();')),
  refusal('page-object', page("({el: document.body}).el.value = 'x';")),
  refusal('array-destructure', page('const [el] = [document.body]; el.click();')),
  refusal('object-destructure', page('const {el} = {el:document.body}; el.value = "x";')),
  refusal('nested-destructure', page('const {box:[el]} = {box:[document.body]}; el.click();')),
  refusal('spread-object', page('const box = {...document}; box.body.click();')),
  refusal('unknown-array', page('const box = [unknown]; box[0].click();')),
  refusal('unknown-object', page('const box = {el:unknown}; box.el.click();')),
  refusal('data-destructure-conservative', page('const {el} = {el:{}}; el.value = "x";')),
  refusal('fetch-destructure', page('const {fetch} = window; fetch("/x");')),
  refusal('fetch-destructure-alias', page('const {fetch: request} = window; request("/x");')),
  refusal('reflect-set', page('Reflect.set(document.body, "innerHTML", "x");')),
  refusal('assign', page('Object.assign(document.body, {innerHTML:"x"});')),
  refusal('define-property', page('Object.defineProperty(document.body, "innerHTML", {value:"x"});')),
  refusal('define-properties', page('Object.defineProperties(document.body, {innerHTML:{value:"x"}});')),
  refusal('submit', page('document.querySelector("form").submit();')),
  refusal('request-submit', page('form.requestSubmit();')),
  refusal('location', page('location = "/x";')),
  refusal('window-location', page('window.location = "/x";')),
  refusal('location-href', page('location.href = "/x";')),
  refusal('cookie', page('document.cookie = "x=y";')),
  refusal('location-destructure', page('({url: location} = source);')),
  refusal('cookie-destructure', page('[document.cookie] = source;')),
  refusal('property-destructure', page('({value:document.body.value} = source);')),
  refusal('eval', page('eval("document.body.click()");')),
  refusal('indirect-eval', page('(0, eval)("document.body.click()");')),
  refusal('function', page('Function("document.body.click()")();')),
  refusal('new-function', page('new Function("document.body.click()")();')),
  refusal('computed-callback-method', page("document.body['cl'+'ick']();")),
  refusal('computed-callback-local', page('const data = {}; data[method]();')),
  refusal('computed-evaluate', `await tab['eval'+'uate'](${click});`),
  refusal('computed-unknown', 'await selected[method](() => document.title);'),
  refusal('computed-unknown-no-evaluate-text', 'await selected[method]();'),
  refusal('interpolated-template', 'await tab.evaluate(`() => ${unknown}`);'),
  refusal('source-string', 'await tab.evaluate("() => document.body.click()");'),
  refusal('source-template', 'await tab.evaluate(`() => document.body.click()`);'),
  refusal('source-script', 'await tab.evaluate("document.body.click()");'),
  refusal('source-alias', 'const cb = "() => document.body.click()"; await tab.evaluate(cb);'),
  refusal('source-invalid', 'await tab.evaluate("(()");'),
  refusal('source-escaped', String.raw`await tab.evaluate("() => document.body.cl\\u0069ck()");`),
  refusal('init-content', 'await tab.addInitScript({content:"document.body.click()"});'),
  refusal('init-path', 'await tab.addInitScript({path:"local.js"});'),
  ...['evaluate', 'evaluateAll', 'evaluateHandle', '$eval', '$$eval', 'addInitScript'].flatMap(method => {
    const arg = ['$eval', '$$eval'].includes(method) ? '"body", ' : '';
    return [
      refusal(`family-${method}`, `await unknown.${method}(${arg}${click});`),
      refusal(`family-string-${method}`, `await unknown.${method}(${arg}"() => document.body.click()");`),
      refusal(`family-escape-${method}`, String.raw`await unknown.${method}(${arg}() => document.body.cl\u0069ck());`),
    ];
  }),
];

export const maskingCases = [
  'Object.assign(tab, {evaluate: f => f()});',
  'Object.defineProperty(tab, "evaluate", {value: f => f()});',
  'Reflect.set(tab, "evaluate", f => f());',
  'Object.setPrototypeOf(tab, {evaluate: f => f()});',
  'Reflect.setPrototypeOf(tab, {evaluate: f => f()});',
  'Object.defineProperties(tab, {evaluate:{value:f=>f()}});',
  'globalThis.tab = {evaluate:f=>f()};',
  '({evaluate: tab.evaluate} = source);',
  '[tab.evaluate] = source;',
  '({tab} = source);',
  'const alias = tab; Object.assign(alias, {evaluate:f=>f()});',
  'const alias = tab; Object.setPrototypeOf(alias, {evaluate:f=>f()});',
  'const box = {tab}; Object.assign(box.tab, {evaluate:f=>f()});',
  'Object.assign(globalThis, {tab: {evaluate:f=>f()}});',
].map((prefix, i) => ({ id: `masking-${i}`, code: `${prefix} await tab.evaluate(() => { app.typeText("x"); return 1; }); await app.getAXState();`,
  write: ![1, 2, 9].includes(i), masked: false, awaiting: 'app.typeText(',
  reason: 'Same-cell receiver mutation invalidates masking, preserving the kernel action diagnostic.' }));

export const safeReviewCases = [
  {id:'literal-key', code:'await data["read"]();', write:false, masked:false},
  {id:'literal-template-key', code:'await data[`read`]();', write:false, masked:false},
  {id:'string-read', code:'await tab.evaluate("() => document.title");', write:false, masked:false},
  {id:'template-read', code:'await tab.evaluate(`() => document.title`);', write:false, masked:false},
  {id:'string-local', code:'const cb = "() => document.title"; await tab.evaluate(cb);', write:true, masked:false},
  {id:'local-object', code:'const h = {evaluate:f=>f()}; await h.evaluate(() => document.body.click());', write:true, masked:false,
    reason:'Local object receivers receive the same write check.'},
  {id:'local-function', code:'function h() {} await h.evaluate(() => document.body.click());', write:true, masked:false,
    reason:'Local function receivers receive the same write check.'},
  {id:'data-array', code:page('const box = [{}]; box[0].value = "x";'), write:false, masked:true},
].map(item => ({...item, id:`safe-review-${item.id}`}));
